56	// commonNamesIn returns the names present in both snapshots, sorted by name
57	// byte order the same way CompareSnapshots walks them.
58	func commonNamesIn(oldSnap, newSnap *SnapshotFile) []string {
59		oldAdj := adjacencyFromValidFile(oldSnap.Graph)
60		newAdj := adjacencyFromValidFile(newSnap.Graph)
61		common := make([]string, 0)
62		for name := range oldAdj {
63			if _, ok := newAdj[name]; ok {
64				common = append(common, name)
65			}
66		}
67		sort.Strings(common)
68		return common
69	}
