190	// TestTraceAndComparePathOnlyRerouteAndShortcutReportsNoSourceChange is the
191	// "same roots, different representative path" case end to end. In the new
192	// version a1 stops depending directly on rootA and hangs off a2 (another
193	// route to the same root), merge gains a shortcut straight to rootA, and down
194	// gains a shortcut straight to rootB. The shortest representative paths of the
195	// trace change for a1, merge, and down, but every common dataset still reaches
196	// exactly the same root set: rootSourceChanges must be empty even though three
197	// direct-upstream relationships genuinely changed.
198	func TestTraceAndComparePathOnlyRerouteAndShortcutReportsNoSourceChange(t *testing.T) {
199		oldSnap := snapshotOf(t, branchOldGraph)
200		newSnap := snapshotOf(t, `{"datasets":[
201			{"name":"rootA","upstreams":[]},
202			{"name":"rootB","upstreams":[]},
203			{"name":"rootC","upstreams":[]},
204			{"name":"a0","upstreams":["rootA"]},
205			{"name":"a1","upstreams":["a0"]},
206			{"name":"a2","upstreams":["rootA","rootC"]},
207			{"name":"b1","upstreams":["rootB"]},
208			{"name":"merge","upstreams":["a1","a2","b1","rootA"]},
209			{"name":"down","upstreams":["merge","rootB"]},
210			{"name":"down2","upstreams":["down"]},
211			{"name":"solo","upstreams":[]}
212		]}`)
213	
214		report := CompareSnapshots(oldSnap, newSnap)
215	
216		if got, want := report.ChangedDatasets, []string{"a1", "down", "merge"}; !reflect.DeepEqual(got, want) {
217			t.Errorf("ChangedDatasets = %v, want %v", got, want)
218		}
219		if got, want := report.AddedRelations, []Relation{
220			{Upstream: "a0", Downstream: "a1"},
221			{Upstream: "rootA", Downstream: "merge"},
222			{Upstream: "rootB", Downstream: "down"},
223		}; !reflect.DeepEqual(got, want) {
224			t.Errorf("AddedRelations = %v, want %v", got, want)
225		}
226		if got, want := report.RemovedRelations, []Relation{
227			{Upstream: "rootA", Downstream: "a1"},
228		}; !reflect.DeepEqual(got, want) {
229			t.Errorf("RemovedRelations = %v, want %v", got, want)
230		}
231		if len(report.RootSourceChanges) != 0 {
232			t.Fatalf("path-only reroutes/shortcuts to the same roots must not report source changes, got %v", report.RootSourceChanges)
233		}
234	
235		// Pin the representative path changes the trace does report, proving the
236		// compare decision is based on the root SET rather than the paths.
237		oldMerge, err := TraceSources(oldSnap, "merge")
238		if err != nil {
239			t.Fatalf("old trace merge: %v", err)
240		}
241		newMerge, err := TraceSources(newSnap, "merge")
242		if err != nil {
243			t.Fatalf("new trace merge: %v", err)
244		}
245		if got, want := oldMerge.Sources, []SourceTrace{
246			{Root: "rootA", Path: []string{"merge", "a1", "rootA"}},
247			{Root: "rootB", Path: []string{"merge", "b1", "rootB"}},
248			{Root: "rootC", Path: []string{"merge", "a2", "rootC"}},
249		}; !reflect.DeepEqual(got, want) {
250			t.Errorf("old merge sources = %+v, want %+v", got, want)
251		}
252		if got, want := newMerge.Sources, []SourceTrace{
253			{Root: "rootA", Path: []string{"merge", "rootA"}},
254			{Root: "rootB", Path: []string{"merge", "b1", "rootB"}},
255			{Root: "rootC", Path: []string{"merge", "a2", "rootC"}},
256		}; !reflect.DeepEqual(got, want) {
257			t.Errorf("new merge sources = %+v, want %+v", got, want)
258		}
259		// down's path to rootB shortens through its new shortcut; rootA keeps
260		// arriving through merge's own shortcut. Root sets are unchanged either
261		// way, and down2 inherits the new routes with no direct edit of its own.
262		newDown := traceReportSources(t, newSnap, "down")
263		if got, want := newDown, []SourceTrace{
264			{Root: "rootA", Path: []string{"down", "merge", "rootA"}},
265			{Root: "rootB", Path: []string{"down", "rootB"}},
266			{Root: "rootC", Path: []string{"down", "merge", "a2", "rootC"}},
267		}; !reflect.DeepEqual(got, want) {
268			t.Errorf("new down sources = %+v, want %+v", got, want)
269		}
270		newDown2 := traceReportSources(t, newSnap, "down2")
271		if got, want := newDown2, []SourceTrace{
272			{Root: "rootA", Path: []string{"down2", "down", "merge", "rootA"}},
273			{Root: "rootB", Path: []string{"down2", "down", "rootB"}},
274			{Root: "rootC", Path: []string{"down2", "down", "merge", "a2", "rootC"}},
275		}; !reflect.DeepEqual(got, want) {
276			t.Errorf("new down2 sources = %+v, want %+v", got, want)
277		}
278		for _, name := range []string{"merge", "down", "down2"} {
279			if got := traceRoots(t, oldSnap, name); !reflect.DeepEqual(got, []string{"rootA", "rootB", "rootC"}) {
280				t.Errorf("old roots of %s = %v, want all three roots", name, got)
281			}
282			if got := traceRoots(t, newSnap, name); !reflect.DeepEqual(got, []string{"rootA", "rootB", "rootC"}) {
283				t.Errorf("new roots of %s = %v, want all three roots", name, got)
284			}
285		}
286	
287		assertTraceAgreesWithCompare(t, oldSnap, newSnap, report)
288	}
