301	// TestTraceAndCompareLastRouteToOldRootLostEverywhere is the root-loss case
302	// across a converged lineage: a1 is repointed from rootA to rootB and a2
303	// drops rootA (keeping rootC), so the merge and BOTH post-merge derivations
304	// lose rootA while rootB and rootC stay reachable through other branches.
305	// merge/down/down2 have unchanged DIRECT upstreams (down2 is two levels away
306	// from the edit), yet all three must be listed with complete old and new root
307	// sets. The traces must report exactly the actually reachable roots, never an
308	// intermediate with upstreams as a root, and never the disconnected "solo".
309	func TestTraceAndCompareLastRouteToOldRootLostEverywhere(t *testing.T) {
310		oldSnap := snapshotOf(t, branchOldGraph)
311		newSnap := snapshotOf(t, `{"datasets":[
312			{"name":"rootA","upstreams":[]},
313			{"name":"rootB","upstreams":[]},
314			{"name":"rootC","upstreams":[]},
315			{"name":"a0","upstreams":["rootA"]},
316			{"name":"a1","upstreams":["rootB"]},
317			{"name":"a2","upstreams":["rootC"]},
318			{"name":"b1","upstreams":["rootB"]},
319			{"name":"merge","upstreams":["a1","a2","b1"]},
320			{"name":"down","upstreams":["merge"]},
321			{"name":"down2","upstreams":["down"]},
322			{"name":"solo","upstreams":[]}
323		]}`)
324	
325		report := CompareSnapshots(oldSnap, newSnap)
326	
327		if len(report.NewDatasets) != 0 || len(report.RemovedDatasets) != 0 {
328			t.Errorf("node lists must be empty, got new=%v removed=%v", report.NewDatasets, report.RemovedDatasets)
329		}
330		if got, want := report.ChangedDatasets, []string{"a1", "a2"}; !reflect.DeepEqual(got, want) {
331			t.Errorf("ChangedDatasets = %v, want only the repointed branches %v", got, want)
332		}
333		if got, want := report.AddedRelations, []Relation{
334			{Upstream: "rootB", Downstream: "a1"},
335		}; !reflect.DeepEqual(got, want) {
336			t.Errorf("AddedRelations = %v, want %v", got, want)
337		}
338		if got, want := report.RemovedRelations, []Relation{
339			{Upstream: "rootA", Downstream: "a1"},
340			{Upstream: "rootA", Downstream: "a2"},
341		}; !reflect.DeepEqual(got, want) {
342			t.Errorf("RemovedRelations = %v, want %v", got, want)
343		}
344	
345		wantChanges := []RootSourceChange{
346			{Dataset: "a1", OldRoots: []string{"rootA"}, NewRoots: []string{"rootB"}},
347			{Dataset: "a2", OldRoots: []string{"rootA", "rootC"}, NewRoots: []string{"rootC"}},
348			{Dataset: "down", OldRoots: []string{"rootA", "rootB", "rootC"}, NewRoots: []string{"rootB", "rootC"}},
349			{Dataset: "down2", OldRoots: []string{"rootA", "rootB", "rootC"}, NewRoots: []string{"rootB", "rootC"}},
350			{Dataset: "merge", OldRoots: []string{"rootA", "rootB", "rootC"}, NewRoots: []string{"rootB", "rootC"}},
351		}
352		if got := report.RootSourceChanges; !reflect.DeepEqual(got, wantChanges) {
353			t.Fatalf("RootSourceChanges = %v\nwant %v", got, wantChanges)
354		}
355	
356		// The lost root must be absent from every new-version trace, present in
357		// every old one; intermediates must never stand in as roots, and the
358		// disconnected solo root must never join a result.
359		for _, name := range []string{"merge", "down", "down2"} {
360			if got := traceRoots(t, oldSnap, name); !reflect.DeepEqual(got, []string{"rootA", "rootB", "rootC"}) {
361				t.Errorf("old roots of %s = %v, want [rootA rootB rootC]", name, got)
362			}
363			if got := traceRoots(t, newSnap, name); !reflect.DeepEqual(got, []string{"rootB", "rootC"}) {
364				t.Errorf("new roots of %s = %v, want only the still reachable [rootB rootC]", name, got)
365			}
366			for _, src := range traceReportSources(t, newSnap, name) {
367				if src.Root == "solo" {
368					t.Errorf("trace of %s must not include disconnected root solo, got %v", name, src)
369				}
370				if src.Root == "merge" || src.Root == "down" || src.Root == "down2" {
371					t.Errorf("intermediate %q must not be reported as a root", src.Root)
372				}
373			}
374		}
375		// rootA itself still exists as a root in both versions and reaches only
376		// itself, so it is not a source change despite being lost downstream.
377		assertDatasetNotAChange(t, report, "rootA")
378		assertNameAbsentFromReport(t, report, "solo")
379	
380		assertTraceAgreesWithCompare(t, oldSnap, newSnap, report)
381	}
