491			r, err := TraceSources(oldSnap, name)
492			if r != nil || err == nil {
493				t.Errorf("old TraceSources(%q) = %+v, %v; want nil report and an error", name, r, err)
494			} else if !errors.Is(err, ErrNotFound) || !strings.Contains(err.Error(), name) {
495				t.Errorf("old TraceSources(%q) err = %v, want ErrNotFound naming %q", name, err, name)
496			}
497		}
498		for _, name := range []string{"gone", "g"} {
499			if r, err := TraceSources(newSnap, name); r != nil || !errors.Is(err, ErrNotFound) {
500				t.Errorf("new TraceSources(%q) = %+v, err=%v; want nil report and ErrNotFound", name, r, err)
501			}
502		}
503	
504		assertTraceAgreesWithCompare(t, oldSnap, newSnap, report)
505	}
506	
507	// TestTraceAndCompareByteOrderCaseAndSpaceRoots pins the ordering the two
508	// reports share when roots differ only by case or surrounding spaces: names
509	// are kept verbatim and ordered by UTF-8 byte order (space 0x20, then "A"
510	// 0x41, then "a" 0x61), both in the trace's sources and in the comparison's
511	// oldRoots/newRoots. n's direct upstream ([M]) never changes; its root set
512	// moves purely because M was repointed.
513	func TestTraceAndCompareByteOrderCaseAndSpaceRoots(t *testing.T) {
514		oldSnap := snapshotOf(t, `{"datasets":[
515			{"name":" A ","upstreams":[]},
516			{"name":"A","upstreams":[]},
517			{"name":"a","upstreams":[]},
518			{"name":"M","upstreams":[" A ","a"]},
519			{"name":"n","upstreams":["M"]}
520		]}`)
521		newSnap := snapshotOf(t, `{"datasets":[
522			{"name":" A ","upstreams":[]},
523			{"name":"A","upstreams":[]},
524			{"name":"a","upstreams":[]},
525			{"name":"M","upstreams":["A","a"]},
526			{"name":"n","upstreams":["M"]}
527		]}`)
528	
529		report := CompareSnapshots(oldSnap, newSnap)
530		wantChanges := []RootSourceChange{
531			{Dataset: "M", OldRoots: []string{" A ", "a"}, NewRoots: []string{"A", "a"}},
532			{Dataset: "n", OldRoots: []string{" A ", "a"}, NewRoots: []string{"A", "a"}},
533		}
534		if got := report.RootSourceChanges; !reflect.DeepEqual(got, wantChanges) {
535			t.Fatalf("RootSourceChanges = %v, want %v", got, wantChanges)
536		}
537	
538		oldM := traceReportSources(t, oldSnap, "M")
539		if got, want := []string{oldM[0].Root, oldM[1].Root}, []string{" A ", "a"}; !reflect.DeepEqual(got, want) {
540			t.Errorf("old M root order = %v, want byte order %v", got, want)
541		}
542		newM := traceReportSources(t, newSnap, "M")
543		if got, want := []string{newM[0].Root, newM[1].Root}, []string{"A", "a"}; !reflect.DeepEqual(got, want) {
544			t.Errorf("new M root order = %v, want byte order %v", got, want)
545		}
546		// The spaced spelling and the single-letter casing are carried verbatim
547		// into the path arrays.
548		if got, want := newM[0].Path, []string{"M", "A"}; !reflect.DeepEqual(got, want) {
549			t.Errorf("new M path to A = %v, want %v", got, want)
550		}
551		if got := traceReportSources(t, newSnap, "n"); !reflect.DeepEqual(got, []SourceTrace{
552			{Root: "A", Path: []string{"n", "M", "A"}},
553			{Root: "a", Path: []string{"n", "M", "a"}},
554		}) {
555			t.Errorf("new n sources = %+v, want verbatim case/space paths", got)
556		}
557	
558		assertTraceAgreesWithCompare(t, oldSnap, newSnap, report)
559	}
560	
561	// TestTraceAndCompareDeterministicAcrossShuffledSemantics feeds the root-loss
562	// scenario in shuffled form (records reordered, upstreams reordered and
563	// repeated) and requires both reports to be byte-identical to the canonical
564	// run, while both input snapshots keep their serialized bytes throughout.
565	func TestTraceAndCompareDeterministicAcrossShuffledSemantics(t *testing.T) {
566		oldCanonical := snapshotOf(t, branchOldGraph)
567		newCanonical := snapshotOf(t, `{"datasets":[
568			{"name":"rootA","upstreams":[]},
569			{"name":"rootB","upstreams":[]},
570			{"name":"rootC","upstreams":[]},
571			{"name":"a0","upstreams":["rootA"]},
572			{"name":"a1","upstreams":["rootB"]},
573			{"name":"a2","upstreams":["rootC"]},
574			{"name":"b1","upstreams":["rootB"]},
575			{"name":"merge","upstreams":["a1","a2","b1"]},
576			{"name":"down","upstreams":["merge"]},
577			{"name":"down2","upstreams":["down"]},
578			{"name":"solo","upstreams":[]}
579		]}`)
580		oldShuffled := snapshotOf(t, `{"datasets":[
581			{"upstreams":[],"name":"solo"},
582			{"name":"down2","upstreams":["down","down"]},
583			{"upstreams":["merge"],"name":"down"},
584			{"name":"merge","upstreams":["b1","a2","a1","a2"]},
585			{"upstreams":["rootB","rootB"],"name":"b1"},
586			{"name":"a2","upstreams":["rootC","rootA"]},
587			{"upstreams":["rootA"],"name":"a1"},
588			{"name":"a0","upstreams":["rootA"]},
589			{"name":"rootC","upstreams":[]},
590			{"name":"rootB","upstreams":[]},
591			{"name":"rootA","upstreams":[]}
592		]}`)
593		newShuffled := snapshotOf(t, `{ "datasets" : [
594			{"name":"solo","upstreams":[]},
595			{"upstreams":["down"],"name":"down2"},
596			{"name":"down","upstreams":["merge","merge"]},
597			{"upstreams":["a2","b1","a1"],"name":"merge"},
598			{"name":"b1","upstreams":["rootB"]},
599			{"name":"a2","upstreams":["rootC","rootC"]},
600			{"name":"a1","upstreams":["rootB"]},
601			{"name":"a0","upstreams":["rootA","rootA"]},
602			{"name":"rootC","upstreams":[]},
603			{"upstreams":[],"name":"rootB"},
604			{"upstreams":[],"name":"rootA"}
605		] }`)
606	
607		wantCompare, err := json.Marshal(CompareSnapshots(oldCanonical, newCanonical))
608		if err != nil {
609			t.Fatalf("marshal canonical compare: %v", err)
610		}
611		gotCompare, err := json.Marshal(CompareSnapshots(oldShuffled, newShuffled))
612		if err != nil {
613			t.Fatalf("marshal shuffled compare: %v", err)
614		}
615		if string(gotCompare) != string(wantCompare) {
616			t.Fatalf("compare reports differ for semantically equal pairs:\n got %s\nwant %s", gotCompare, wantCompare)
617		}
618	
619		// Every trace over the shuffled snapshots equals the canonical trace, both
620		// the root sets and the representative paths.
621		for _, name := range commonNamesIn(oldCanonical, newCanonical) {
622			wantOld, err := TraceSources(oldCanonical, name)
623			if err != nil {
624				t.Fatalf("canonical old trace %q: %v", name, err)
625			}
626			wantNew, err := TraceSources(newCanonical, name)
627			if err != nil {
628				t.Fatalf("canonical new trace %q: %v", name, err)
629			}
630			gotOld, err := TraceSources(oldShuffled, name)
631			if err != nil {
632				t.Fatalf("shuffled old trace %q: %v", name, err)
633			}
634			gotNew, err := TraceSources(newShuffled, name)
635			if err != nil {
636				t.Fatalf("shuffled new trace %q: %v", name, err)
637			}
638			if !reflect.DeepEqual(gotOld, wantOld) {
639				t.Errorf("old trace %q differs across equivalent spellings:\n got %+v\nwant %+v", name, gotOld, wantOld)
640			}
641			if !reflect.DeepEqual(gotNew, wantNew) {
642				t.Errorf("new trace %q differs across equivalent spellings:\n got %+v\nwant %+v", name, gotNew, wantNew)
643			}
644		}
645	
646		// Read-only: the snapshots handed to both reports serialize identically
647		// before and after.
648		oldBytes, err := MarshalSnapshot(oldCanonical)
649		if err != nil {
650			t.Fatalf("marshal old: %v", err)
651		}
652		newBytes, err := MarshalSnapshot(newCanonical)
653		if err != nil {
654			t.Fatalf("marshal new: %v", err)
655		}
656		_ = CompareSnapshots(oldCanonical, newCanonical)
657		for _, name := range commonNamesIn(oldCanonical, newCanonical) {
658			if _, err := TraceSources(oldCanonical, name); err != nil {
659				t.Fatalf("trace old %q: %v", name, err)
660			}
661			if _, err := TraceSources(newCanonical, name); err != nil {
662				t.Fatalf("trace new %q: %v", name, err)
663			}
664		}
665		if got, err := MarshalSnapshot(oldCanonical); err != nil || string(got) != string(oldBytes) {
666			t.Errorf("old snapshot changed during reports: %v", err)
667		}
668		if got, err := MarshalSnapshot(newCanonical); err != nil || string(got) != string(newBytes) {
669			t.Errorf("new snapshot changed during reports: %v", err)
670		}
671	}
