198	// TestTraceReorderingAndRemovingSourcesLeavesSnapshotAndRequeryUntouched pins
199	// the array-level edits: swapping the two source records, mutating a path after
200	// the swap, and dropping a record from the array must not move the snapshot,
201	// and a fresh query still reports both roots with their full original paths.
202	func TestTraceReorderingAndRemovingSourcesLeavesSnapshotAndRequeryUntouched(t *testing.T) {
203		snap := snapshotOf(t, traceIndependenceGraphJSON)
204		wantID := snap.ContentID
205		snapshotBytes := mustMarshalSnapshot(t, snap)
206	
207		report := traceReportOf(t, snap, "T")
208		report.Sources[0], report.Sources[1] = report.Sources[1], report.Sources[0]
209	
210		// After the swap each record still owns its own complete path.
211		if got, ok := sourceForRoot(report, "R1"); !ok || !reflect.DeepEqual(got, wantIndependenceTSources[0]) {
212			t.Errorf("R1 after swap = %+v ok=%v, want %+v", got, ok, wantIndependenceTSources[0])
213		}
214		if got, ok := sourceForRoot(report, "R2"); !ok || !reflect.DeepEqual(got, wantIndependenceTSources[1]) {
215			t.Errorf("R2 after swap = %+v ok=%v, want %+v", got, ok, wantIndependenceTSources[1])
216		}
217		// Mutating through the swapped position edits the record now held there
218		// (R2's), never R1's record.
219		report.Sources[0].Path[0] = "HACK"
220		if got, ok := sourceForRoot(report, "R1"); !ok || !reflect.DeepEqual(got, wantIndependenceTSources[0]) {
221			t.Errorf("R1 changed after editing the swapped R2 record: %+v ok=%v", got, ok)
222		}
223	
224		// A separate report from which the caller removes one record.
225		pruned := traceReportOf(t, snap, "T")
226		pruned.Sources = pruned.Sources[:1]
227		if len(pruned.Sources) != 1 || pruned.Sources[0].Root != "R1" {
228			t.Fatalf("pruned report = %+v, want only R1", pruned.Sources)
229		}
230	
231		// The snapshot is unchanged: content id, graph, export bytes.
232		if snap.ContentID != wantID {
233			t.Errorf("content id changed: %q", snap.ContentID)
234		}
235		if got := snapshotDatasetsCopy(snap); !reflect.DeepEqual(got, wantIndependenceSnapshotDatasets) {
236			t.Errorf("snapshot changed:\n got %v\nwant %v", got, wantIndependenceSnapshotDatasets)
237		}
238		if got := mustMarshalSnapshot(t, snap); !bytes.Equal(got, snapshotBytes) {
239			t.Errorf("snapshot export changed:\n got %s\nwant %s", got, snapshotBytes)
240		}
241	
242		// A fresh query still sees both roots and both full paths.
243		fresh := traceReportOf(t, snap, "T")
244		if !reflect.DeepEqual(fresh.Sources, wantIndependenceTSources) {
245			t.Errorf("fresh query after edits = %+v, want %+v", fresh.Sources, wantIndependenceTSources)
246		}
247		if fresh.ContentID != snap.ContentID || fresh.Dataset != "T" {
248			t.Errorf("fresh report metadata = %q %q, want %q %q", fresh.ContentID, fresh.Dataset, snap.ContentID, "T")
249		}
250	}
