95	// and exactly the datasets with differing traced root sets appear in
96	// rootSourceChanges.
97	func TestCLICompareAndTraceAgreeOnRootExplanations(t *testing.T) {
98		oldPath := snapshotForTrace(t, cliConsistencyOldGraph)
99		newPath := snapshotForTrace(t, cliConsistencyNewGraph)
100		oldBytes, newBytes := readFile(t, oldPath), readFile(t, newPath)
