107		}
108		var report chainledger.CompareReport
109		if err := json.Unmarshal([]byte(stdout), &report); err != nil {
110			t.Fatalf("compare stdout is not valid JSON: %v\n%s", err, stdout)
111		}
112	
113		// Direct-change and version-only classifications stay exactly as the
114		// underlying rules state; root-source explanation is checked separately.
115		if got, want := report.NewDatasets, []string{"born"}; !reflect.DeepEqual(got, want) {
116			t.Errorf("NewDatasets = %v, want %v", got, want)
117		}
118		if got, want := report.RemovedDatasets, []string{"gone"}; !reflect.DeepEqual(got, want) {
119			t.Errorf("RemovedDatasets = %v, want %v", got, want)
120		}
121		if got, want := report.ChangedDatasets, []string{"a1", "a2", "clear", "q"}; !reflect.DeepEqual(got, want) {
122			t.Errorf("ChangedDatasets = %v, want %v", got, want)
123		}
124	
125		wantChanges := []chainledger.RootSourceChange{
126			{Dataset: "a1", OldRoots: []string{"rootA"}, NewRoots: []string{"rootB"}},
127			{Dataset: "a2", OldRoots: []string{"rootA", "rootC"}, NewRoots: []string{"rootC"}},
128			{Dataset: "after", OldRoots: []string{"rootA"}, NewRoots: []string{"clear"}},
129			{Dataset: "clear", OldRoots: []string{"rootA"}, NewRoots: []string{"clear"}},
130			{Dataset: "down", OldRoots: []string{"rootA", "rootB", "rootC"}, NewRoots: []string{"rootB", "rootC"}},
131			{Dataset: "merge", OldRoots: []string{"rootA", "rootB", "rootC"}, NewRoots: []string{"rootB", "rootC"}},
132		}
133		if got := report.RootSourceChanges; !reflect.DeepEqual(got, wantChanges) {
134			t.Fatalf("RootSourceChanges = %v\nwant %v", got, wantChanges)
135		}
136	
137		// Every common dataset: reconcile compare's recorded sets against actual
138		// trace command output in each frozen snapshot.
139		common := []string{
140			"rootA", "rootB", "rootC", "a0", "a1", "a2", "b1",
141			"merge", "down", "q", "clear", "after",
142		}
143		sort.Strings(common)
144		listed := map[string]bool{}
145		for _, change := range report.RootSourceChanges {
146			listed[change.Dataset] = true
147			if got := traceRootNamesCLI(t, oldPath, change.Dataset); !reflect.DeepEqual(got, change.OldRoots) {
148				t.Errorf("%s: old trace roots %v != compare oldRoots %v", change.Dataset, got, change.OldRoots)
149			}
150			if got := traceRootNamesCLI(t, newPath, change.Dataset); !reflect.DeepEqual(got, change.NewRoots) {
151				t.Errorf("%s: new trace roots %v != compare newRoots %v", change.Dataset, got, change.NewRoots)
152			}
153		}
154		for _, name := range common {
155			oldRoots := traceRootNamesCLI(t, oldPath, name)
156			newRoots := traceRootNamesCLI(t, newPath, name)
157			differ := !reflect.DeepEqual(oldRoots, newRoots)
158			if differ != listed[name] {
159				t.Errorf("dataset %q: traced sets differ=%v but rootSourceChanges presence=%v (old=%v new=%v)",
160					name, differ, listed[name], oldRoots, newRoots)
161			}
162		}
163	
164		// Path-only change: q's representative path changes (rootA becomes two
165		// relations away via a0), yet its root set stays {rootA} and compare does
166		// not list it. Both trace paths are complete arrays ending at rootA.
167		oldQ := traceCLI(t, oldPath, "q")
168		newQ := traceCLI(t, newPath, "q")
