170			{Root: "rootA", Path: []string{"q", "rootA"}},
171		}; !reflect.DeepEqual(got, want) {
172			t.Errorf("old q sources = %+v, want %+v", got, want)
173		}
174		if got, want := newQ.Sources, []chainledger.SourceTrace{
175			{Root: "rootA", Path: []string{"q", "a0", "rootA"}},
176		}; !reflect.DeepEqual(got, want) {
177			t.Errorf("new q sources = %+v, want %+v (path changed, root did not)", got, want)
178		}
179		if listed["q"] {
180			t.Errorf("q must not be a root-source change when only its path changed")
181		}
182	
183		// The cleared dataset traces itself only, as a single-element path, in the
184		// new version; its unchanged-direct-upstream child after reports it as the
185		// sole root too.
186		if got, want := traceCLI(t, newPath, "clear").Sources,
187			[]chainledger.SourceTrace{{Root: "clear", Path: []string{"clear"}}}; !reflect.DeepEqual(got, want) {
188			t.Errorf("new clear sources = %+v, want single-element self path %+v", got, want)
189		}
190		if got, want := traceCLI(t, newPath, "after").Sources,
191			[]chainledger.SourceTrace{{Root: "clear", Path: []string{"after", "clear"}}}; !reflect.DeepEqual(got, want) {
192			t.Errorf("new after sources = %+v, want %+v", got, want)
193		}
194	
195		// Neither report may mistake an intermediate with upstreams for a root:
196		// merge/down never appear as roots in any trace.
197		for _, snapPath := range []string{oldPath, newPath} {
198			for _, name := range common {
199				for _, src := range traceCLI(t, snapPath, name).Sources {
200					if src.Root == "merge" || src.Root == "down" || src.Root == "a1" || src.Root == "a2" || src.Root == "b1" || src.Root == "after" {
201						t.Errorf("trace of %q in %s reports intermediate %q as a root: %+v", name, snapPath, src.Root, src)
202					}
203				}
204			}
205		}
206	
207		// Version-only datasets stay out of rootSourceChanges, trace successfully
208		// where they exist, and fail with no success output where they do not.
209		for _, change := range report.RootSourceChanges {
210			if change.Dataset == "born" || change.Dataset == "gone" {
211				t.Errorf("version-only dataset %q must not appear in rootSourceChanges", change.Dataset)
212			}
213		}
214		if got := traceRootNamesCLI(t, newPath, "born"); !reflect.DeepEqual(got, []string{"rootB"}) {
215			t.Errorf("new trace born roots = %v, want [rootB]", got)
216		}
217		if got := traceRootNamesCLI(t, oldPath, "gone"); !reflect.DeepEqual(got, []string{"rootA"}) {
218			t.Errorf("old trace gone roots = %v, want [rootA]", got)
219		}
220		for _, tc := range []struct {
221			snapPath, dataset string
222		}{
223			{oldPath, "born"},
224			{newPath, "gone"},
225		} {
226			out, stderr, exitCode := captureStdout(t, func() int {
227				return run([]string{"trace", tc.snapPath, tc.dataset})
228			})
229			if exitCode == 0 {
230				t.Errorf("trace %q in snapshot missing it succeeded, want failure", tc.dataset)
231			}
232			if out != "" {
233				t.Errorf("trace %q in snapshot missing it wrote success output %q", tc.dataset, out)
234			}
235			if !strings.Contains(stderr, tc.dataset) || !strings.Contains(stderr, tc.snapPath) {
236				t.Errorf("trace %q stderr = %q, must name the dataset and snapshot file", tc.dataset, stderr)
237			}
238		}
239	
240		// Both commands are read-only: the snapshot files are byte-for-byte
241		// unchanged after compare and every trace.
242		if got := readFile(t, oldPath); got != oldBytes {
243			t.Errorf("old snapshot modified:\n got %s\nwant %s", got, oldBytes)
244		}
245		if got := readFile(t, newPath); got != newBytes {
246			t.Errorf("new snapshot modified:\n got %s\nwant %s", got, newBytes)
247		}
248	}
249	
250	// TestCLICompareAndTraceStableAcrossEquivalentSpellings feeds the same
251	// transition with records shuffled, upstreams reordered and repeated, and JSON
252	// whitespace changed: compare output must be byte-identical and every trace
253	// output must be byte-identical to the canonical-spelling run.
254	func TestCLICompareAndTraceStableAcrossEquivalentSpellings(t *testing.T) {
255		oldCanonical := snapshotForTrace(t, cliConsistencyOldGraph)
256		newCanonical := snapshotForTrace(t, cliConsistencyNewGraph)
257	
258		oldShuffledGraph := `{ "datasets" : [
259			{"upstreams":["rootA"],"name":"gone"},
260			{"name":"after","upstreams":["clear","clear"]},
261			{"upstreams":["rootA"],"name":"clear"},
262			{"upstreams":["rootA","rootA"],"name":"q"},
263			{"name":"down","upstreams":["merge"]},
264			{"upstreams":["a1","a2","b1","a2"],"name":"merge"},
265			{"name":"b1","upstreams":["rootB"]},
266			{"upstreams":["rootC","rootA"],"name":"a2"},
267			{"name":"a1","upstreams":["rootA"]},
268			{"name":"a0","upstreams":["rootA"]},
269			{"name":"rootC","upstreams":[]},
270			{"upstreams":[],"name":"rootB"},
271			{"upstreams":[],"name":"rootA"}
272		] }`
273		newShuffledGraph := `{"datasets":[
274			{"upstreams":["rootB"],"name":"born"},
275			{"upstreams":["clear"],"name":"after"},
276			{"name":"clear","upstreams":[]},
277			{"name":"q","upstreams":["a0"]},
278			{"upstreams":["merge","merge"],"name":"down"},
279			{"name":"merge","upstreams":["b1","a2","a1"]},
280			{"upstreams":["rootB"],"name":"b1"},
281			{"name":"a2","upstreams":["rootC","rootC"]},
282			{"name":"a1","upstreams":["rootB"]},
283			{"upstreams":["rootA"],"name":"a0"},
284			{"name":"rootC","upstreams":[]},
285			{"name":"rootB","upstreams":[]},
286			{"name":"rootA","upstreams":[]}
287		]}`
288		oldShuffled := snapshotForTrace(t, oldShuffledGraph)
289		newShuffled := snapshotForTrace(t, newShuffledGraph)
290	
291		compareOut := func(oldSnap, newSnap string) string {
292			t.Helper()
293			out, stderr, exitCode := captureStdout(t, func() int {
294				return run([]string{"compare", oldSnap, newSnap})
295			})
296			if exitCode != 0 {
297				t.Fatalf("compare exit = %d, stderr = %s", exitCode, stderr)
298			}
299			return out
300		}
301		canonicalCompare := compareOut(oldCanonical, newCanonical)
302		if got := compareOut(oldShuffled, newShuffled); got != canonicalCompare {
303			t.Fatalf("compare differs across equivalent spellings:\n got %s\nwant %s", got, canonicalCompare)
304		}
305	
306		for _, dataset := range []string{
307			"rootA", "rootB", "rootC", "a0", "a1", "a2", "b1",
308			"merge", "down", "q", "clear", "after",
309		} {
310			traceOut := func(snapPath string) string {
311				t.Helper()
312				out, stderr, exitCode := captureStdout(t, func() int {
313					return run([]string{"trace", snapPath, dataset})
314				})
315				if exitCode != 0 {
316					t.Fatalf("trace %q exit = %d, stderr = %s", dataset, exitCode, stderr)
317				}
318				return out
319			}
320			if got := traceOut(oldShuffled); got != traceOut(oldCanonical) {
321				t.Errorf("old trace %q differs across equivalent spellings", dataset)
322			}
323			if got := traceOut(newShuffled); got != traceOut(newCanonical) {
324				t.Errorf("new trace %q differs across equivalent spellings", dataset)
325			}
326		}
327	
328		// Shuffled-graph snapshots carry the same content identifiers as the
329		// canonical ones because content addressing sees only semantics.
330		oldCanonID := parseSnapshotID(t, oldCanonical)
331		newCanonID := parseSnapshotID(t, newCanonical)
332		if got := parseSnapshotID(t, oldShuffled); got != oldCanonID {
333			t.Errorf("old shuffled contentId = %q, want %q", got, oldCanonID)
334		}
335		if got := parseSnapshotID(t, newShuffled); got != newCanonID {
336			t.Errorf("new shuffled contentId = %q, want %q", got, newCanonID)
337		}
338	}
339	
340	// parseSnapshotID reads a snapshot file through the public parser and returns
341	// its content identifier.
342	func parseSnapshotID(t *testing.T, path string) string {
343		t.Helper()
344		snap, err := chainledger.ParseSnapshot([]byte(readFile(t, path)))
345		if err != nil {
346			t.Fatalf("parse snapshot %s: %v", path, err)
347		}
348		return snap.ContentID
349	}
350

